// 增强版微信文章HTML内容解析
const cheerio = require('cheerio');

// 获取HTML内容
let html = '';
if ($input.first().json.data) {
    html = $input.first().json.data;
} else if ($input.first().json.body) {
    html = $input.first().json.body;
} else {
    html = $input.first().json || '';
}

if (!html) {
    return {
        error: 'No HTML content found',
        title: '无法获取内容',
        content: '抓取失败，可能是访问限制或链接无效',
        url: $input.first().json.article_url || '',
        extracted_at: new Date().toISOString()
    };
}

const $ = cheerio.load(html);

// 增强标题提取
let title = '';
const titleSelectors = [
    '#activity-name',
    '.rich_media_title',
    'h1.title',
    'h1',
    '.weui-msg__title',
    'title',
    '[data-role="title"]'
];

for (const selector of titleSelectors) {
    const element = $(selector);
    if (element.length > 0 && element.text().trim()) {
        title = element.text().trim();
        break;
    }
}

// 增强正文内容提取
let content = '';
const contentSelectors = [
    '#js_content',
    '.rich_media_content', 
    '.article-content',
    '.content',
    '[data-role="content"]',
    '.weui-article__bd',
    'div[data-role="outer"] .rich_media_content',
    'div.rich_media_area_primary'
];

for (const selector of contentSelectors) {
    const element = $(selector);
    if (element.length > 0) {
        // 移除脚本和样式标签
        element.find('script, style, .rich_media_tool, .profile_container').remove();
        content = element.text().trim();
        if (content.length > 100) { // 确保获取到足够的内容
            break;
        }
    }
}

// 如果还是没有内容，尝试获取整个body的文本
if (!content || content.length < 50) {
    $('script, style, nav, footer, header, .ad, .advertisement').remove();
    content = $('body').text().trim();
}

// 清理内容
if (content) {
    content = content
        .replace(/\s+/g, ' ')
        .replace(/微信号.*?功能介绍/g, '')
        .replace(/长按二维码识别.*?$/g, '')
        .replace(/点击上方.*?关注/g, '')
        .replace(/阅读原文.*?$/g, '')
        .replace(/\d+人点赞/g, '')
        .replace(/分享.*?朋友圈/g, '')
        .trim();
}

// 获取原始链接
const originalUrl = $input.first().json.article_url || '';

// 返回提取的数据
return {
    title: title || '未获取到标题',
    content: content || '未获取到正文内容',
    url: originalUrl,
    extracted_at: new Date().toISOString(),
    debug_info: {
        html_length: html.length,
        title_found: !!title,
        content_length: content.length
    }
};

// 处理DeepSeek API响应
const aiResponse = $input.first().json;
let summary = '';

try {
    if (aiResponse.choices && aiResponse.choices.length > 0) {
        summary = aiResponse.choices[0].message.content.trim();
    } else {
        summary = '总结生成失败';
    }
} catch (error) {
    summary = '总结解析错误: ' + error.message;
}

// 合并所有数据
const previousData = $input.first().json;
return {
    ...previousData,
    summary: summary,
    processed_at: new Date().toISOString(),
    processing_status: 'completed'
};
